using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Mistletoe;

/// <summary>
/// Mistletoe, a green ball of forked twigs and white berries on a fallen branch in the Mistlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py; the branch stays and the mistletoe grows back. Nothing else gives it.
/// </summary>
public class Mistletoe : ForageableBase
{
    /// <summary>
    /// Prefab name of the mistletoe item.
    /// </summary>
    public const string PrefabName = "WhiteHiltMistletoe";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Mistletoe";

    /// <inheritdoc/>
    protected override string Description => "A green ball of forked twigs and white berries that grows high in old trees and falls with their branches. The mistletoe killed Baldr; brewed with care, it wakes the eitr instead.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 1,
        GroupRadius = 2f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "mistletoeitem", 0.15f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "mistletoe", 0.45f);
    }
}
